// The half of a generated client that is the same in every application. `client.ts`
// beside it is the half that is this one's: its endpoints, its tables and their
// rows.

/** How a client reaches its server. */
export interface ClientOptions {
  /** Prepended to every request path. */
  baseUrl?: string;
  /** Fetch implementation to use (defaults to global `fetch`). */
  fetch?: typeof fetch;
  /** How the live connection behaves, for an application that exposes streams. */
  live?: LiveOptions;
}

/** A failed request, as the error a caller sees: status, and what the server said. */
export async function clientError(op: string, res: Response): Promise<Error> {
  let detail = "";
  try {
    const body: unknown = await res.json();
    if (body && typeof body === "object" && "error" in body && typeof (body as { error: unknown }).error === "string") {
      detail = `: ${(body as { error: string }).error}`;
    }
  } catch {
    // Non-JSON body: the status alone will have to describe the failure.
  }
  return new Error(`${op} failed: ${res.status}${detail}`);
}

/** The CSRF token the server last named in a response, for a client that
 * cannot read the cookie. */
let rememberedCsrf: string | undefined;

function csrfToken(): string | undefined {
  if (typeof document !== "undefined") {
    for (const part of document.cookie.split(";")) {
      const [name, ...rest] = part.trim().split("=");
      if (name === "sc_csrf") return decodeURIComponent(rest.join("="));
    }
  }
  return rememberedCsrf;
}

/** `fetchImpl`, remembering the CSRF token each response names — how a client
 * with no `document.cookie` learns what its next write must echo.
 *
 * A write refused `403` with a token it did not send is sent **once more** with
 * that token: a native app reopened while still signed in has its session but
 * not the token it remembered, and its first write is how it finds out. */
export function trackCsrf(fetchImpl: typeof fetch): typeof fetch {
  return (async (input: Parameters<typeof fetch>[0], init?: Parameters<typeof fetch>[1]) => {
    const res = await fetchImpl(input, init);
    const token = res.headers.get("x-csrf-token");
    if (token) rememberedCsrf = token;
    const sent = new Headers(init?.headers).get("x-csrf-token");
    if (res.status === 403 && token && token !== sent) {
      const headers = new Headers(init?.headers);
      headers.set("x-csrf-token", token);
      return fetchImpl(input, { ...init, headers });
    }
    return res;
  }) as typeof fetch;
}

/** The headers a request carries: its content type, its CSRF token, and — where
 * there is no `document`, i.e. a native app — that it is not a browser, so the
 * server lets its login outlive the app being closed. */
export function requestHeaders(method: string, hasBody: boolean): Record<string, string> {
  const headers: Record<string, string> = {};
  if (hasBody) headers["content-type"] = "application/json";
  if (typeof document === "undefined") headers["x-feldspar-client"] = "native";
  if (method !== "GET" && method !== "HEAD") {
    const token = csrfToken();
    if (token) headers["x-csrf-token"] = token;
  }
  return headers;
}

// --- reading a table --------------------------------------------------------

/** What a delete answers with. */
export type Deleted = { deleted: true };

/** A comparison a filter may name. */
export type FilterOp =
  | "eq"
  | "ne"
  | "gt"
  | "gte"
  | "lt"
  | "lte"
  | "in"
  | "nin"
  | "like"
  | "ilike"
  | "is_null";

/** One column's filter: a comparison and its operand, e.g. `gte.2020-01-01`. */
export type FilterValue = `${FilterOp}.${string}`;

/** The filters a read may carry — one per column of the table being read. */
export type Filters<Row> = Partial<Record<Extract<keyof Row, string>, FilterValue>>;

/** One `order` key: a column, ascending unless it says otherwise. */
export type OrderKey<Row> =
  | Extract<keyof Row, string>
  | `${Extract<keyof Row, string>}.asc`
  | `${Extract<keyof Row, string>}.desc`;

/** `order`: one key, or a precedence list of them. */
export type Order<Row> = OrderKey<Row> | `${OrderKey<Row>},${string}`;

/** Flatten an intersection, so a hover shows the object rather than the pieces. */
type Flatten<T> = { [K in keyof T]: T[K] } & {};

/**
 * A write body over a table's row: `Required` must be given, everything else may
 * be, and `ReadOnly` cannot be given at all.
 *
 * A row and an insert hold the same columns with the same types and differ only
 * in which of them the *caller* has to supply — so a generated client says that
 * difference as two lists of column names rather than as a second copy of the
 * table, which could describe a different one.
 */
export type Insertable<
  Row,
  Required extends keyof Row,
  ReadOnly extends keyof Row = never,
> = Flatten<Pick<Row, Required> & Partial<Omit<Row, Required | ReadOnly>>>;

/** The bytes behind a file column. */
export interface FileApi<Id> {
  /** Read them. */
  download(id: Id): Promise<Blob>;
  /** Replace them with `body`, stored under `filename`. */
  upload(id: Id, filename: string, body: BodyInit): Promise<unknown>;
}

// --- the type of a `select` -------------------------------------------------
//
// A `select` changes the shape of what comes back, so what a read *returns* is a
// function of the string the caller wrote: `list({ select: "title,author(name)" })`
// answers `{ title, author: { name } }` and nothing else. The types below are
// that function, evaluated by the compiler — which is why there is one `list`
// rather than one for rows and another for embeds.
//
// A select assembled at runtime (typed `string`, not a literal) cannot be read
// this way. It degrades to the whole row plus unknown extras rather than
// failing: the compiler then knows exactly what the caller does.

/** A table's row type, and the tables its keys point at. */
export type TableSchema = { row: object; rels: { [field: string]: TableSchema } };

type Trim<S extends string> = S extends ` ${infer R}`
  ? Trim<R>
  : S extends `${infer R} `
    ? Trim<R>
    : S;

/** Split a select list on its top-level commas — the ones outside any `(…)`. */
type SplitItems<
  S extends string,
  Depth extends 0[] = [],
  Item extends string = "",
  Out extends string[] = [],
> = S extends `${infer C}${infer Rest}`
  ? C extends "("
    ? SplitItems<Rest, [...Depth, 0], `${Item}${C}`, Out>
    : C extends ")"
      ? SplitItems<
          Rest,
          Depth extends [0, ...infer Less extends 0[]] ? Less : [],
          `${Item}${C}`,
          Out
        >
      : C extends ","
        ? Depth["length"] extends 0
          ? SplitItems<Rest, Depth, "", [...Out, Item]>
          : SplitItems<Rest, Depth, `${Item}${C}`, Out>
        : SplitItems<Rest, Depth, `${Item}${C}`, Out>
  : [...Out, Item];

/** The type of one column — `unknown` for a name the table does not have. */
type ColumnOf<S extends TableSchema, Name extends string> = Name extends keyof S["row"]
  ? S["row"][Name]
  : unknown;

/**
 * The type of one embed: what was selected on the far side, and `null` when the
 * key itself is nullable — a null key answers `null` rather than an object of
 * nulls.
 */
type EmbedOf<S extends TableSchema, Name extends string, Inner extends string> = Name extends
  keyof S["rels"]
  ? Name extends keyof S["row"]
    ? null extends S["row"][Name]
      ? Selected<S["rels"][Name], Inner> | null
      : Selected<S["rels"][Name], Inner>
    : Selected<S["rels"][Name], Inner>
  : unknown;

/** One select item: `column`, `alias:column`, `key(…)` or `alias:key(…)`. */
type ItemOf<S extends TableSchema, Item extends string> = Trim<Item> extends
  `${infer Alias}:${infer Target}`
  ? { [K in Trim<Alias>]: TargetOf<S, Trim<Target>> }
  : Trim<Item> extends `${infer Name}(${infer Inner})`
    ? { [K in Trim<Name>]: EmbedOf<S, Trim<Name>, Inner> }
    : { [K in Trim<Item>]: ColumnOf<S, Trim<Item>> };

/** What an item points at, once any alias has been taken off the front. */
type TargetOf<S extends TableSchema, Target extends string> = Target extends
  `${infer Name}(${infer Inner})`
  ? EmbedOf<S, Trim<Name>, Inner>
  : ColumnOf<S, Target>;

type ItemsOf<S extends TableSchema, Items extends string[]> = {
  [I in keyof Items]: ItemOf<S, Items[I] & string>;
}[number];

type UnionToIntersection<U> = (U extends unknown ? (x: U) => void : never) extends
  (x: infer I) => void
  ? I
  : never;

/** What a read with the select `Sel` answers with. */
export type Selected<S extends TableSchema, Sel extends string> = string extends Sel
  ? S["row"] & Record<string, unknown>
  : Trim<Sel> extends ""
    ? S["row"]
    : Flatten<UnionToIntersection<ItemsOf<S, SplitItems<Sel>>>>;

// --- live updates -----------------------------------------------------------

/** Where a live connection is: connecting for the first time, open, or reconnecting after a loss. */
export type LiveStatus = "connecting" | "open" | "reconnecting";

/** What the server says when a subscription starts (and again if its stream restarts). */
export interface LiveReady {
  stream: string;
  /** How many of the elements that follow are history, not new arrivals. */
  replayed: number;
  /** What an element's `value` is, or `null` while the stream is not running on the server. */
  element_type: unknown;
  /** Whether this subscriber may publish on the stream. */
  can_publish: boolean;
  status: unknown;
  counters: unknown;
}

/** Why the server refused, ended or complained about a subscription. */
export interface LiveError {
  /** `unavailable`, `revoked`, `invalid`, `too_many_subscriptions`, `signed_out`, … */
  code: string;
  message: string;
}

/** What a subscriber is told. Only `element` is required. */
export interface LiveHandlers<E> {
  ready?(info: LiveReady): void;
  element(envelope: E): void;
  /** This subscription fell behind and lost `dropped` elements (it is never a silent gap). */
  lagged?(dropped: number): void;
  /** The connection was lost and re-established: anything built from earlier elements may be stale. */
  resync?(): void;
  status?(status: unknown): void;
  /** A refusal. Before `ready`, or as `revoked`, it ends the subscription, which is not retried. */
  error?(error: LiveError): void;
}

/** A live subscription. `close()` ends it. */
export interface LiveSubscription {
  close(): void;
}

/** One stream an application exposes, ready to subscribe to — or one row's topic of a row stream. */
export interface LiveStream<E> {
  readonly name: string;
  /** The connection it is subscribed over, for its `status`. */
  readonly connection: LiveConnection;
  subscribe(handlers: LiveHandlers<E>): LiveSubscription;
}

/** A row's key, as a topic: `"7"` and `7` name the same row. */
export type LiveTopic = string | number;

/** A stream with a topic per row: subscribe naming the row's key. */
export interface LiveRowStream<E> {
  readonly name: string;
  readonly connection: LiveConnection;
  subscribe(topic: LiveTopic, handlers: LiveHandlers<E>): LiveSubscription;
  /** One row's topic as a stream of its own — the same object for the same key, so a hook can depend on it. */
  topic(topic: LiveTopic): LiveStream<E>;
}

/** How a live connection behaves. */
export interface LiveOptions {
  /** The `WebSocket` constructor to use (defaults to the global one). */
  WebSocket?: typeof WebSocket;
  /** The first reconnect delay, in milliseconds. */
  minDelay?: number;
  /** The longest reconnect delay, in milliseconds. */
  maxDelay?: number;
}

/** The live socket's URL: `path` on the client's base URL, as `ws:` or `wss:`. */
export function liveUrl(baseUrl: string, path: string): string {
  const origin = baseUrl || (typeof location === "undefined" ? "http://localhost" : location.origin);
  const url = new URL(path, origin);
  url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
  return url.toString();
}

/** A `subscribe` frame: the topic and the filter only when there is one. */
function subscribeFrame(
  sub: string,
  stream: string,
  topic: string | undefined,
  filter: Record<string, unknown> | undefined,
): Record<string, unknown> {
  const frame: Record<string, unknown> = { type: "subscribe", sub, stream };
  if (topic !== undefined) frame["topic"] = topic;
  if (filter !== undefined) frame["filter"] = filter;
  return frame;
}

type LiveEntry = {
  stream: string;
  topic: string | undefined;
  filter: Record<string, unknown> | undefined;
  handlers: LiveHandlers<unknown>;
  ready: boolean;
};

/** One socket, any number of subscriptions, reconnecting by itself. */
export class LiveConnection {
  private socket: WebSocket | undefined;
  private readonly entries = new Map<string, LiveEntry>();
  private readonly listeners = new Set<(status: LiveStatus) => void>();
  private nextSub = 1;
  private attempt = 0;
  private opened = false;
  private timer: ReturnType<typeof setTimeout> | undefined;
  private current: LiveStatus = "connecting";
  // Fields assigned in the body rather than as parameter properties: Node runs
  // this file by stripping its types, and a parameter property is not erasable.
  private readonly url: string;
  private readonly options: LiveOptions;

  constructor(url: string, options: LiveOptions = {}) {
    this.url = url;
    this.options = options;
  }

  /** Where the connection is now. */
  get status(): LiveStatus {
    return this.current;
  }

  /** Be told when the status changes. Returns the function that stops it. */
  onStatus(listener: (status: LiveStatus) => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /** The accessor for the stream called `name` — one with no topic, or whose topic is the subscriber's own. */
  stream<E>(name: string): LiveStream<E> {
    return {
      name,
      connection: this,
      subscribe: (handlers: LiveHandlers<E>) => this.subscribe(name, handlers),
    };
  }

  /** The accessor for the stream called `name`, whose topics are rows. */
  rowStream<E>(name: string): LiveRowStream<E> {
    const topics = new Map<string, LiveStream<E>>();
    return {
      name,
      connection: this,
      subscribe: (topic: LiveTopic, handlers: LiveHandlers<E>) =>
        this.subscribe(name, handlers, String(topic)),
      topic: (topic: LiveTopic) => {
        const key = String(topic);
        let stream = topics.get(key);
        if (!stream) {
          stream = {
            name,
            connection: this,
            subscribe: (handlers: LiveHandlers<E>) => this.subscribe(name, handlers, key),
          };
          topics.set(key, stream);
        }
        return stream;
      },
    };
  }

  /** The accessor for the stream called `name`, of the changes to `table`, whose primary key is `key`. */
  changesStream<Sch extends TableSchema, Key = LiveTopic>(
    name: string,
    table: string,
    key: string,
  ): LiveChangesStream<Sch, Key> {
    return {
      name,
      table,
      key,
      connection: this,
      subscribe: (query, handlers) => {
        const where = query.where === undefined ? undefined : whereObject(query.where);
        return this.subscribe(name, handlers, undefined, where);
      },
    };
  }

  /**
   * Subscribe to `stream` (on `topic`, for a row stream; with `filter`, the
   * filter object, for a stream of changes), opening the socket if this is the
   * first subscription.
   */
  subscribe<E>(
    stream: string,
    handlers: LiveHandlers<E>,
    topic?: string,
    filter?: Record<string, unknown>,
  ): LiveSubscription {
    const sub = `s${this.nextSub++}`;
    this.entries.set(sub, { stream, topic, filter, handlers: handlers as LiveHandlers<unknown>, ready: false });
    if (this.socket && this.socket.readyState === 1) {
      this.send(subscribeFrame(sub, stream, topic, filter));
    } else {
      this.open();
    }
    let active = true;
    return {
      close: () => {
        if (!active) return;
        active = false;
        if (this.entries.delete(sub) && this.socket && this.socket.readyState === 1) {
          this.send({ type: "unsubscribe", sub });
        }
        if (this.entries.size === 0) this.shutdown();
      },
    };
  }

  /** End every subscription and close the socket. */
  close(): void {
    this.entries.clear();
    this.shutdown();
  }

  private setStatus(status: LiveStatus): void {
    if (status === this.current) return;
    this.current = status;
    this.listeners.forEach((listener) => listener(status));
  }

  private send(frame: Record<string, unknown>): void {
    this.socket?.send(JSON.stringify(frame));
  }

  private open(): void {
    if (this.socket || this.timer !== undefined) return;
    const Socket = this.options.WebSocket ?? (typeof WebSocket === "undefined" ? undefined : WebSocket);
    if (!Socket) throw new Error("live updates need a WebSocket implementation (LiveOptions.WebSocket)");
    const socket = new Socket(this.url);
    this.socket = socket;
    socket.onopen = () => {
      const reconnect = this.opened;
      this.opened = true;
      this.attempt = 0;
      this.setStatus("open");
      this.entries.forEach((entry, sub) => {
        entry.ready = false;
        this.send(subscribeFrame(sub, entry.stream, entry.topic, entry.filter));
        if (reconnect) entry.handlers.resync?.();
      });
    };
    socket.onmessage = (event: MessageEvent) => this.receive(event.data);
    socket.onclose = () => {
      if (this.socket !== socket) return;
      this.socket = undefined;
      if (this.entries.size === 0) return;
      this.setStatus("reconnecting");
      const min = this.options.minDelay ?? 500;
      const max = this.options.maxDelay ?? 30000;
      const delay = Math.min(max, min * 2 ** this.attempt);
      this.attempt += 1;
      // Half the delay, plus up to half again at random: a server that restarts
      // is not met by every page reconnecting in the same millisecond.
      this.timer = setTimeout(() => {
        this.timer = undefined;
        this.open();
      }, delay / 2 + Math.random() * (delay / 2));
    };
  }

  private shutdown(): void {
    if (this.timer !== undefined) {
      clearTimeout(this.timer);
      this.timer = undefined;
    }
    const socket = this.socket;
    this.socket = undefined;
    this.opened = false;
    this.attempt = 0;
    socket?.close();
    this.setStatus("connecting");
  }

  private receive(data: unknown): void {
    let frame: Record<string, unknown>;
    try {
      const parsed: unknown = JSON.parse(String(data));
      if (!parsed || typeof parsed !== "object") return;
      frame = parsed as Record<string, unknown>;
    } catch {
      return;
    }
    const sub = typeof frame["sub"] === "string" ? frame["sub"] : undefined;
    const entry = sub === undefined ? undefined : this.entries.get(sub);
    switch (frame["type"]) {
      case "ready":
        if (entry) {
          entry.ready = true;
          entry.handlers.ready?.(frame as unknown as LiveReady);
        }
        break;
      case "element":
        entry?.handlers.element(frame["envelope"]);
        break;
      case "lagged":
        entry?.handlers.lagged?.(Number(frame["dropped"] ?? 0));
        break;
      case "status":
        entry?.handlers.status?.(frame["status"]);
        break;
      case "revoked":
        if (entry && sub !== undefined) {
          this.entries.delete(sub);
          entry.handlers.error?.({ code: "revoked", message: "access to this stream ended" });
        }
        break;
      case "error": {
        const error: LiveError = {
          code: String(frame["code"] ?? "error"),
          message: String(frame["message"] ?? ""),
        };
        if (sub === undefined) {
          // About the connection, not one subscription: everyone hears it, and
          // the reconnect that follows a close asks again.
          this.entries.forEach((each) => each.handlers.error?.(error));
        } else if (entry) {
          // Refused before `ready`: the subscription never started, so it ends.
          if (!entry.ready) this.entries.delete(sub);
          entry.handlers.error?.(error);
        }
        break;
      }
      default:
        // A frame this client was generated before: ignored, never thrown on.
        break;
    }
  }
}

// --- live rows --------------------------------------------------------------

/**
 * One change to a table's rows, as one subscriber is sent it. `insert`,
 * `update` and `enter` (a row came into this subscriber's view) carry the row
 * unless the stream sends keys only; `leave` (a row left the view) and `delete`
 * never do.
 */
export type LiveChange<Row, Key = LiveTopic> =
  | { op: "insert" | "update" | "enter"; key: Key; row?: Row }
  | { op: "leave" | "delete"; key: Key; row?: undefined };

/** An element of a stream in its envelope, its `value` typed `V`. */
export type LiveEnvelope<V> = {
  stream: string;
  /** The topic it was published on, for a stream with topics. */
  topic?: string;
  value: V;
  /** When *this server* saw it — not a claim about when it was produced. */
  received_at: string;
  source?: unknown;
};

/** Which rows a subscription to a table's changes is about: the REST read's own filters. */
export type LiveChangesQuery<Row> = { where?: Filters<Row> };

/** A stream of a table's changes: subscribe with the filter a read of the table would use. */
export interface LiveChangesStream<Sch extends TableSchema, Key = LiveTopic> {
  readonly name: string;
  readonly connection: LiveConnection;
  /** The table whose changes these are. */
  readonly table: string;
  /** Its primary key's column, which every change's `key` is a value of. */
  readonly key: string;
  subscribe(
    query: LiveChangesQuery<Sch["row"]>,
    handlers: LiveHandlers<LiveEnvelope<LiveChange<Sch["row"], Key>>>,
  ): LiveSubscription;
}

/**
 * A REST read's `Filters` as the socket's filter object: `{ board: "eq.7" }`
 * is `{ board: { eq: "7" } }`, `in.(1,2)` a list, `is_null.true` a boolean —
 * the same lowering the server gives a query string, so a read and a
 * subscription with one filter are about the same rows.
 */
export function whereObject(filters: { readonly [column: string]: string | undefined }): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [column, spec] of Object.entries(filters)) {
    if (spec === undefined) continue;
    const dot = spec.indexOf(".");
    if (dot < 0) {
      throw new Error(`\`${column}: "${spec}"\` is not a filter: a filter is "op.value", e.g. "eq.${spec}"`);
    }
    const op = spec.slice(0, dot);
    out[column] = { [op]: filterOperand(op, spec.slice(dot + 1)) };
  }
  return out;
}

/** One operand as the server reads it: text, except a list for `in`/`nin` and a boolean for `is_null`. */
function filterOperand(op: string, operand: string): unknown {
  if (op === "in" || op === "nin") {
    if (!operand.startsWith("(") || !operand.endsWith(")")) return operand;
    const items: string[] = [];
    let current = "";
    let quoted = false;
    for (const c of operand.slice(1, -1)) {
      if (c === '"') quoted = !quoted;
      else if (c === "," && !quoted) {
        items.push(current);
        current = "";
      } else current += c;
    }
    if (current !== "" || items.length > 0) items.push(current);
    return items;
  }
  if (op === "is_null") return operand === "true" ? true : operand === "false" ? false : operand;
  return operand;
}

/** How a read's rows are kept: by which key, in which order, cut to which columns. */
export interface LiveRowsPlan {
  /** The primary key's column. */
  key: string;
  /** The order the rows are kept in, most significant first. */
  order: Array<{ column: string; desc: boolean }>;
  /** The columns a change's row is cut to, or `undefined` for whole rows. */
  columns: string[] | undefined;
  /** Whether a change's row cannot stand in for a read, so changed rows are read again. */
  refetch: boolean;
  /** The `select` the read is made with: the caller's, plus the key and order columns it needs. */
  select: string | undefined;
}

/** The top-level items of a `select`: split on the commas outside any `(…)`. */
function selectItems(select: string): string[] {
  const items: string[] = [];
  let depth = 0;
  let current = "";
  for (const c of select) {
    if (c === "(") depth += 1;
    if (c === ")") depth = Math.max(0, depth - 1);
    if (c === "," && depth === 0) {
      items.push(current.trim());
      current = "";
    } else current += c;
  }
  items.push(current.trim());
  return items.filter((item) => item !== "");
}

/** Plan how the rows of a read with `orderBy` and `select` are kept, by the key column `key`. */
export function liveRowsPlan(key: string, options: { orderBy?: string; select?: string } = {}): LiveRowsPlan {
  const order = (options.orderBy ?? "")
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item !== "")
    .map((item) => {
      const [column, direction] = item.split(".");
      return { column: column ?? item, desc: direction === "desc" };
    });
  const items = selectItems(options.select ?? "");
  if (items.length === 0) return { key, order, columns: undefined, refetch: false, select: undefined };
  // An embed or an alias answers something other than the table's row: the
  // stream's row cannot stand in for it.
  const refetch = items.some((item) => item.includes("(") || item.includes(":"));
  const needed = [key, ...order.map((o) => o.column)].filter((column) => !items.includes(column));
  const all = [...items, ...needed.filter((column, i) => needed.indexOf(column) === i)];
  return { key, order, columns: refetch ? undefined : all, refetch, select: all.join(",") };
}

/** Two column values in an order's sense: nulls last (ascending), numbers as numbers, text by code unit. */
function compareValues(a: unknown, b: unknown): number {
  const aNull = a === null || a === undefined;
  const bNull = b === null || b === undefined;
  if (aNull || bNull) return aNull === bNull ? 0 : aNull ? 1 : -1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  if (typeof a === "boolean" && typeof b === "boolean") return Number(a) - Number(b);
  const x = typeof a === "string" ? a : JSON.stringify(a);
  const y = typeof b === "string" ? b : JSON.stringify(b);
  return x < y ? -1 : x > y ? 1 : 0;
}

/** `rows` in the plan's order — a stable sort, so ties keep the order they had. */
export function sortLiveRows<R>(rows: readonly R[], plan: LiveRowsPlan): R[] {
  if (plan.order.length === 0) return [...rows];
  return [...rows].sort((a, b) => {
    for (const { column, desc } of plan.order) {
      const c = compareValues((a as Record<string, unknown>)[column], (b as Record<string, unknown>)[column]);
      if (c !== 0) return desc ? -c : c;
    }
    return 0;
  });
}

/** A row's key, as text: `7` and `"7"` are the same row. */
function rowKey(row: unknown, plan: LiveRowsPlan): string {
  return String((row as Record<string, unknown>)[plan.key]);
}

/** A change's row cut to the plan's columns. */
function cutRow(row: object, plan: LiveRowsPlan): object {
  if (plan.columns === undefined) return row;
  const out: Record<string, unknown> = {};
  for (const column of plan.columns) out[column] = (row as Record<string, unknown>)[column];
  return out;
}

/** `rows` with `row` put in place of the row with its key, or added, and in order. */
function upsertRow<R>(rows: readonly R[], row: R, plan: LiveRowsPlan): R[] {
  const key = rowKey(row, plan);
  const at = rows.findIndex((each) => rowKey(each, plan) === key);
  const next = [...rows];
  if (at >= 0) next[at] = row;
  else next.push(row);
  return sortLiveRows(next, plan);
}

/** What applying one change does: the rows after it, and a key to read again if the change could not say. */
export interface LiveRowsStep<R> {
  rows: R[];
  refetch?: unknown;
}

/**
 * Apply one change to a read's rows. `leave` and `delete` take the row out;
 * `insert`, `update` and `enter` put it in, in order — or, when the change has
 * no row or its row is not what the read answers, leave the rows as they are
 * and name the key to read again.
 */
export function applyLiveChange<R>(
  rows: readonly R[],
  change: LiveChange<unknown, unknown>,
  plan: LiveRowsPlan,
): LiveRowsStep<R> {
  const key = String(change.key);
  switch (change.op) {
    case "leave":
    case "delete":
      return { rows: rows.filter((row) => rowKey(row, plan) !== key) };
    case "insert":
    case "update":
    case "enter":
      if (change.row === undefined || change.row === null || plan.refetch) {
        return { rows: [...rows], refetch: change.key };
      }
      return { rows: upsertRow(rows, cutRow(change.row as object, plan) as R, plan) };
    default:
      // An op this client was generated before: read the row again rather than guess.
      return { rows: [...rows], refetch: (change as { key: unknown }).key };
  }
}

/**
 * The rows a read of `keys` answered, merged into `rows`: each key the read
 * answered is put in place, and each it did not — deleted, or no longer
 * readable — is taken out.
 */
export function mergeLiveRows<R>(
  rows: readonly R[],
  keys: readonly unknown[],
  read: readonly R[],
  plan: LiveRowsPlan,
): R[] {
  const answered = new Map(read.map((row) => [rowKey(row, plan), row]));
  let next = [...rows];
  for (const key of keys.map(String)) {
    const row = answered.get(key);
    next = row === undefined ? next.filter((each) => rowKey(each, plan) !== key) : upsertRow(next, row, plan);
  }
  return next;
}

/** An `in.(…)` list item, quoted when it holds a comma or a quote of its own. */
function listItem(key: unknown): string {
  const text = String(key);
  return /[,"()]/.test(text) ? `"${text.replace(/"/g, "")}"` : text;
}

/** How rows are read and kept live: the read's filter, order and `select`. */
export type LiveRowsOptions<Row, S extends string = ""> = {
  /** The read's filters, and the subscription's — one value for both. */
  where?: Filters<Row>;
  orderBy?: Order<Row>;
  select?: S;
};

/** A table the client reads and whose changes the application exposes: what `LiveRows` needs. */
export interface LiveTable<Sch extends TableSchema = TableSchema, Key = LiveTopic> {
  list(query?: { select?: string; filter?: Filters<Sch["row"]>; order?: Order<Sch["row"]> }): Promise<unknown[]>;
  readonly changes: LiveChangesStream<Sch, Key>;
}

/** What `LiveRows` holds: the rows, whether a read is in flight, and the last failure. */
export interface LiveRowsState<R> {
  rows: R[];
  /** A full read is in flight (the first, or one after a reconnect or a lag). */
  loading: boolean;
  /** A read that failed, or the server refusing the subscription. */
  error: Error | LiveError | undefined;
}

/**
 * A read of a table kept current by its changes: reads once the subscription
 * is ready, applies each change, and reads again after a reconnect or a lag.
 * `current` is a new object after every change and the same object between
 * them, so it can back `useSyncExternalStore` as it stands.
 */
export class LiveRows<R> {
  private state: LiveRowsState<R> = { rows: [], loading: true, error: undefined };
  private readonly listeners = new Set<() => void>();
  private subscription: LiveSubscription | undefined;
  private generation = 0;
  private reading = false;
  private waiting: Array<LiveChange<unknown, unknown>> = [];
  private readonly versions = new Map<string, number>();
  private readonly pending = new Map<string, unknown>();
  private scheduled = false;
  private readonly table: LiveTable<TableSchema, unknown>;
  private readonly options: LiveRowsOptions<object, string>;
  readonly plan: LiveRowsPlan;

  constructor(table: LiveTable<TableSchema, unknown>, options: LiveRowsOptions<object, string> = {}) {
    this.table = table;
    this.options = options;
    this.plan = liveRowsPlan(table.changes.key, {
      orderBy: options.orderBy as string | undefined,
      select: options.select,
    });
  }

  /** The rows as they are now. */
  get current(): LiveRowsState<R> {
    return this.state;
  }

  /** Be told after every change to `current`. Returns the function that stops it. */
  onChange(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /** Subscribe, and read once the subscription is ready. Starting again after `close` is allowed. */
  start(): void {
    if (this.subscription) return;
    this.subscription = this.table.changes.subscribe(
      { where: this.options.where },
      {
        // The first `ready`, and the one after every reconnect (`resync`):
        // what arrived while the socket was down is gone, so read it all again.
        ready: () => this.refresh(),
        element: (envelope) => this.receive(envelope.value),
        lagged: () => this.refresh(),
        error: (error) => this.set({ ...this.state, loading: false, error }),
      },
    );
  }

  /** Stop following the table. */
  close(): void {
    this.generation += 1;
    this.reading = false;
    this.waiting = [];
    this.pending.clear();
    this.subscription?.close();
    this.subscription = undefined;
  }

  /** Read every row again; changes that arrive meanwhile are applied on top. */
  refresh(): void {
    const generation = ++this.generation;
    this.reading = true;
    this.waiting = [];
    this.pending.clear();
    if (!this.state.loading) this.set({ ...this.state, loading: true });
    this.table
      .list({ select: this.plan.select, filter: this.options.where, order: this.options.orderBy })
      .then(
        (rows) => {
          if (generation !== this.generation) return;
          this.reading = false;
          let next = rows as R[];
          const waiting = this.waiting;
          this.waiting = [];
          for (const change of waiting) next = this.step(next, change);
          this.set({ rows: next, loading: false, error: undefined });
        },
        (error: unknown) => {
          if (generation !== this.generation) return;
          this.reading = false;
          this.set({ ...this.state, loading: false, error: error instanceof Error ? error : new Error(String(error)) });
        },
      );
  }

  private set(state: LiveRowsState<R>): void {
    this.state = state;
    this.listeners.forEach((listener) => listener());
  }

  private receive(change: LiveChange<unknown, unknown>): void {
    if (this.reading) {
      this.waiting.push(change);
      return;
    }
    this.set({ ...this.state, rows: this.step(this.state.rows, change) });
  }

  /** Apply one change, counting it against its key and asking for the key again if the change could not say. */
  private step(rows: R[], change: LiveChange<unknown, unknown>): R[] {
    const key = String(change.key);
    this.versions.set(key, (this.versions.get(key) ?? 0) + 1);
    const step = applyLiveChange<R>(rows, change, this.plan);
    if (step.refetch !== undefined) this.schedule(step.refetch);
    return step.rows;
  }

  private schedule(key: unknown): void {
    this.pending.set(String(key), key);
    if (this.scheduled) return;
    this.scheduled = true;
    queueMicrotask(() => {
      this.scheduled = false;
      this.readKeys();
    });
  }

  /** Read the keys changes could not say enough about, in one read. */
  private readKeys(): void {
    const keys = Array.from(this.pending.values());
    this.pending.clear();
    if (keys.length === 0) return;
    const generation = this.generation;
    const asked = new Map(keys.map((key) => [String(key), this.versions.get(String(key)) ?? 0]));
    const filter = { [this.plan.key]: `in.(${keys.map(listItem).join(",")})` } as Filters<object>;
    this.table.list({ select: this.plan.select, filter }).then(
      (rows) => {
        if (generation !== this.generation) return;
        // A key a newer change has moved on from is that change's to settle.
        const current = keys.filter((key) => (this.versions.get(String(key)) ?? 0) === asked.get(String(key)));
        this.set({ ...this.state, rows: mergeLiveRows(this.state.rows, current, rows as R[], this.plan) });
      },
      (error: unknown) => {
        if (generation !== this.generation) return;
        this.set({ ...this.state, error: error instanceof Error ? error : new Error(String(error)) });
      },
    );
  }
}

